def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    prefix_len = len(prefix)
    suffix_len = len(suffix)
    for i in range(len(s) - prefix_len + 1):
        if s[i:i + prefix_len] == prefix:
            # Check if there is enough space for suffix
            if i + prefix_len + suffix_len > len(s):
                continue
            if s[i + prefix_len - 1:i + prefix_len - 1 + suffix_len] == suffix:
                return True
            # Allow for the empty case of suffix
            if suffix_len == 0:
                return True
    return False

from typing import List


def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    rows = len(grid)
    cols = len(grid[0])

    for i in range(rows):
        if i % 2 == 0:
            # Traverse left to right
            for j in range(cols):
                if j % 2 == 0:
                    result.append(grid[i][j])
        else:
            # Traverse right to left
            for j in range(cols - 1, -1, -1):
                if j % 2 == 0:
                    result.append(grid[i][j])

    return result

from collections import Counter

def findValidPair(s: str) -> str:
    count = Counter(s)
    for i in range(len(s) - 1):
        a, b = s[i], s[i + 1]
        if a != b and count[a] == int(a) and count[b] == int(b):
            return a + b
    return ""

