def maxSum(nums: List[int]) -> int:
    unique_values = set(nums)
    max_sum = float('-inf')

    for value in unique_values:
        current_sum = 0
        for num in nums:
            if num == value:
                current_sum += num
            elif current_sum > 0:
                max_sum = max(max_sum, current_sum)
                current_sum = 0
        max_sum = max(max_sum, current_sum)  # check at the end for the last segment

    return max_sum if max_sum != float('-inf') else 0

