from typing import List


def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [1] * n  # dp[i] tracks the length of the longest subsequence ending at index i
    last_diff = [[0] * (n) for _ in range(n)]  # last_diff[i][j] stores the last difference for subsequence ending at j with the previous element at i
    max_length = 1

    for i in range(n):
        for j in range(i):
            diff = abs(nums[i] - nums[j])  # Calculate the absolute difference between nums[i] and nums[j]
            if dp[j] >= 1:  # Only consider valid subsequences
                valid = True
                # Check the last difference in the subsequence ending at j
                for k in range(1, j + 1):
                    if last_diff[j][k] and last_diff[j][k] < diff:
                        valid = True
                    else:
                        valid = False
                        break
                if valid:
                    dp[i] = max(dp[i], dp[j] + 1)
                    max_length = max(max_length, dp[i])
                last_diff[j][i] = diff
    return max_length

from typing import List


def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    # dp[i][j][k] will store the maximum coins at (i, j) with k neutralizations used
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # start at (0, 0) and must take the value here

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k is the number of neutralizations used
                if i == 0 and j == 0:
                    continue
                # Move from the left cell (i, j-1)
                if j > 0:
                    if coins[i][j] < 0 and k > 0:
                        # Neutralize the robber
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + 0)
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + coins[i][j])
                # Move from the top cell (i-1, j)
                if i > 0:
                    if coins[i][j] < 0 and k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + 0)
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + coins[i][j])

    # The result will be the maximum coins at the bottom-right corner with up to 2 neutralizations
    return max(dp[m-1][n-1][0], dp[m-1][n-1][1], dp[m-1][n-1][2])

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *args = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(args[0])
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            # Process users coming back online before this message
            for user_id in range(numberOfUsers):
                if not online_status[user_id] and timestamp >= offline_until[user_id]:
                    online_status[user_id] = True

            mentions_string = args[0]
            if mentions_string == "ALL":
                for user_id in range(numberOfUsers):
                    mentions[user_id] += 1
            elif mentions_string == "HERE":
                for user_id in range(numberOfUsers):
                    if online_status[user_id]:
                        mentions[user_id] += 1
            else:
                mentioned_ids = mentions_string.split()
                for mention in mentioned_ids:
                    if mention.startswith("id"):
                        user_id = int(mention[2:])
                        mentions[user_id] += 1

    return mentions
